if(Array.isArray(db.properties)){const p5=db.properties.find(p=>p.id==='p5');if(p5&&p5.image===img('skyline.jpg'))p5.image=img('skyline-clean.jpg');}
const persist = () => {try{localStorage.setItem(KEY,JSON.stringify(db));isPersistent=true;return true;}catch(e){isPersistent=false;notice('Browser storage is unavailable or full; data may not persist.',true);return false;}};
